/// <summary>
/// Extension class for <c>InventTransferUpdShip</c>.
/// </summary>
[ExtensionOf(classStr(InventTransferUpdShip))]
final class METInventTransferUpdShip_Extension
{
}

Method.Source:
/// <summary>
///    Updates an <c>InventTransferLine</c> record.
/// </summary>
/// <param name="_inventTransferParmLine">
///    The <c>InventTransferParmLine</c> record that defines the <c>InventTransferLine</c> record to be
///    updated.
/// </param>
/// <remarks>
///    The method should not update the related <c>InventTransferTable</c> record. The record will be
///    updated by the caller after all lines are updated.
/// </remarks>
protected void updateInventTransferLine(InventTransferParmLine  _inventTransferParmLine)
{
    // Update the InventDim of the receive transaction to match the ship transaction
    if (inventTransferParmTable.AutoReceiveQty)
    {
        this.metUpdateInventTransReceive(_inventTransferParmLine);
    }

    next updateInventTransferLine(_inventTransferParmLine);
}

/// <summary>
/// Updates the InventDim of the receive transaction to match the ship transaction
/// </summary>
/// <param name = "_inventTransferParmLine">InventTransferParmLine</param>
private void metUpdateInventTransReceive(InventTransferParmLine  _inventTransferParmLine)
{
    InventTransferLine inventTransferLine = InventTransferLine::findTransIdShip(_inventTransferParmLine.InventTransId);
    InventTransOrigin inventTransOriginReceive = InventTransOrigin::findByInventTransId(inventTransferLine.InventTransIdReceive);
    InventTrans inventTransReceive = InventTrans::findByInventTransOrigin(inventTransOriginReceive.RecId);
    InventDim inventDimReceive = inventTransReceive.inventDim();
    InventDim inventDimShip = inventTransferLine.inventDim();

    if (inventDimReceive.wMSLocationId != inventDimShip.wMSLocationId)
    {
        inventTransReceive.selectForUpdate(true);
        inventTransReceive.InventDimId = this.metChangeInventDimReceiveWMSLocation(inventDimReceive, inventDimShip).InventDimId;
        inventTransReceive.update();
    }
}

/// <summary>
/// Creates an <c>InventUpd_Financial</c> instance that is used for the Physical and financial receive receipt update of the transfer line.
/// </summary>
/// <param name = "_parameters">Parameters used to create the <c>InventUpd_Financial</c> instance.</param>
/// <returns>The created <c>InventUpd_Financial</c> instance.</returns>
protected InventUpd_Financial createInventUpdFinancialReceiptAutoReceive(InventUpdFinancialReceiptAutoReceiveCreateParameters _parameters)
{
    InventUpdFinancialReceiptAutoReceiveCreateParameters parameters = _parameters;

    // Update the InventDim of the receive transaction to match the ship transaction
    if (inventTransferParmTable.AutoReceiveQty)
    {
        parameters = this.metUpdateInventUpdFinancialReceiptAutoReceiveCreateParameters(parameters);
    }

    return next createInventUpdFinancialReceiptAutoReceive(parameters);
}

/// <summary>
/// Updates the InventDim in the InventUpdFinancialReceiptAutoReceiveCreateParameters to match the ship InventDim
/// </summary>
/// <param name = "_parameters">InventUpdFinancialReceiptAutoReceiveCreateParameters</param>
/// <returns>InventUpdFinancialReceiptAutoReceiveCreateParameters</returns>
private InventUpdFinancialReceiptAutoReceiveCreateParameters metUpdateInventUpdFinancialReceiptAutoReceiveCreateParameters(InventUpdFinancialReceiptAutoReceiveCreateParameters _parameters)
{
    InventUpdFinancialReceiptAutoReceiveCreateParameters parameters = _parameters;

    InventTransferLine inventTransferLine = InventTransferLine::findTransIdShip(parameters.inventTransferParmLine.InventTransId);
    InventDim inventDimShip = inventTransferLine.inventDim();
    InventDim inventDimReceive = _parameters.inventDimTo;

    if (inventDimReceive.wMSLocationId != inventDimShip.wMSLocationId)
    {
        InventDim inventDimUpdate = this.metChangeInventDimReceiveWMSLocation(inventDimReceive, inventDimShip);
        parameters.inventDimTo = inventDimUpdate;
    }

    return parameters;
}

/// <summary>
/// Changes the WMS Location of the receive InventDim to match the ship InventDim
/// </summary>
/// <param name = "_inventDimReceive">InventDim</param>
/// <param name = "_inventDimShip">InventDim</param>
/// <returns>InventDim</returns>
private InventDim metChangeInventDimReceiveWMSLocation(InventDim _inventDimReceive, InventDim _inventDimShip)
{
    InventDim inventDimUpdate = _inventDimReceive.data();
    inventDimUpdate.wMSLocationId = _inventDimShip.wMSLocationId;
    inventDimUpdate = InventDim::findOrCreate(inventDimUpdate);
    return inventDimUpdate;
}
